def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 5 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            gaps = [x for x in range(c0+1, c1) if grid[r0][x] == 0]
            if r0 + 1 <= r1 and gaps:
                for y in range(r0+1, r1):
                    for x in range(c0+1, c1):
                        if out[y][x] == 0:
                            out[y][x] = 2
                gap = gaps[0]
                direction = -1 if gap-c0 > c1-gap else 1
                x = gap
                if r0 > 0:
                    while 0 <= x < w:
                        if out[r0-1][x] != 0:
                            break
                        out[r0-1][x] = 2
                        x += direction
    return out

